716	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
717	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
718	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
719	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
720	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
721	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次。只读查询，
722	// 不改变事项、交接进度或班次结束时记录。
723	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
724		itemID = clean(itemID)
725		d := &svc.store.data
726		it, _ := findItem(d, itemID)
727		if it == nil {
728			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
729		}
730		j := ItemJourney{Item: *it}
731	
732		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
733		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
734		// 该轮重新提交、后续处理）。
735		type keyedEvent struct {
736			ev    JourneyEvent
737			group string // "" 表示事项自身事件，否则为交接编号
738			ord   int    // 同一（时刻、分组）内的先后
739		}
740		var events []keyedEvent
741		seq := 0
742		add := func(ev JourneyEvent, group string) {
743			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
744			seq++
745		}
746	
747		// received 事件与交接中的接收处理是同一次接收，只展示一次（以交接事件
748		// 展示，信息更全）；匹配不上的旧数据 received 事件仍原样保留。
749		receivedUsed := make([]bool, len(it.Events))
750	
751		hs := append([]Handover(nil), d.Handovers...)
752		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
753		for k := range hs {
754			h := &hs[k]
755			e, _ := findEntry(h, itemID)
756			if e == nil {
757				continue
758			}
759			j.HasHandovers = true
760			j.Results = append(j.Results, EntryView{
761				HandoverID: h.ID,
762				FromShift:  h.FromShiftID,
763				ToShift:    h.ToShiftID,
764				Entry:      *e,
765			})
766	
767			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
768			add(JourneyEvent{
769				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
770				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
771			}, h.ID)
772			for _, r := range e.Rounds {
773				add(JourneyEvent{
774					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
775					Kind: "return", Operator: r.ReturnOperator,
776					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
777					RoundSeq: r.Seq, Reason: r.Reason,
778				}, h.ID)
779				if r.ResubmittedAt != nil {
780					add(JourneyEvent{
781						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
782						Kind: "resubmit", Operator: r.SupplementOperator,
783						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
784						RoundSeq: r.Seq, Supplement: r.Supplement,
785						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
786					}, h.ID)
787				}
788			}
789			if e.Status.Received() {
790				kind := "confirm"
791				if e.Status == EntryTracking {
792					kind = "track"
793				}
794				ev := JourneyEvent{
795					Kind: kind, Operator: e.Operator,
796					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
797					TrackingNote: e.TrackingNote,
798					// 继续跟踪当时指定的后续负责人取自交接记录快照，
799					// 之后修改事项负责人不改变这里的历史值。
800					FollowOwner: e.FollowOwner,
801				}
802				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
803				// 时间标为未记录，排在有真实时间的事件之后。
804				if validProcessedAt(e.ProcessedAt) {
805					ev.At, ev.TimeKnown = *e.ProcessedAt, true
806				}
807				add(ev, h.ID)
808				if validProcessedAt(e.ProcessedAt) {
809					for i := range it.Events {
810						iev := &it.Events[i]
811						if iev.Kind == "received" && !receivedUsed[i] &&
812							iev.At.Equal(*e.ProcessedAt) && iev.Operator == e.Operator {
813							receivedUsed[i] = true
814							break
815						}
816					}
817				}
818			}
819		}
820	
821		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
822		// received 事件（旧数据）也保留。
823		for i, iev := range it.Events {
824			if iev.Kind == "received" && receivedUsed[i] {
825				continue
826			}
827			add(JourneyEvent{
828				At: iev.At, TimeKnown: !iev.At.IsZero(),
829				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
830			}, "")
831		}
832	
833		sort.SliceStable(events, func(i, k int) bool {
834			a, b := events[i], events[k]
835			if a.ev.TimeKnown != b.ev.TimeKnown {
836				return a.ev.TimeKnown
837			}
838			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
839				return a.ev.At.Before(b.ev.At)
840			}
841			if a.group != b.group {
842				return a.group < b.group
843			}
844			return a.ord < b.ord
845		})
846		for _, ke := range events {
847			j.Events = append(j.Events, ke.ev)
848		}
849		return j, nil
850	}
851	
852	// GetHandover 按编号查询交接。
853	func (svc *Service) GetHandover(id string) (Handover, error) {
854		h, _ := findHandover(&svc.store.data, clean(id))
855		if h == nil {
856			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
857		}
858		return *h, nil
859	}
860	
861	// ListHandovers 返回全部交接记录，按编号排序。
862	func (svc *Service) ListHandovers() []Handover {
863		out := append([]Handover(nil), svc.store.data.Handovers...)
864		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
865		return out
866	}
867	
868	// OverlapNotes 返回涉及指定班次的全部重叠说明。
869	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
870		shiftID = clean(shiftID)
871		out := []OverlapNote{}
872		for _, n := range svc.store.data.Notes {
873			if n.ShiftA == shiftID || n.ShiftB == shiftID {
874				out = append(out, n)
875			}
876		}
877		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
878		return out
879	}
880	
881	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
882	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
883	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
884	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
885		shiftID = clean(shiftID)
886		d := &svc.store.data
887		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
888		sh, _ := findShift(d, shiftID)
889		if sh == nil {
890			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
891		}
892		rep.Shift = *sh
893	
894		for _, n := range d.Notes {
895			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
896				rep.OverlapNotes = append(rep.OverlapNotes, n)
897			}
898		}
899		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
900	
901		switch {
902		case !sh.Closed:
903			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
904			rep.Items = currentItemsOfShift(d, sh.ID)
905		case sh.CloseRecord != nil:
906			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
907			rep.ItemsAtClose = true
908			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
909			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
910			for _, s := range rep.CloseItems {
911				if it, _ := findItem(d, s.ItemID); it != nil {
912					rep.LatestItems[s.ItemID] = *it
913				}
914			}
915		default:
916			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
917			rep.HistoryIncomplete = true
918			rep.Items = currentItemsOfShift(d, sh.ID)
919		}
920		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
921	
922		for i := range d.Handovers {
923			h := &d.Handovers[i]
924			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
925			if !involved {
926				continue
927			}
928			if h.FromShiftID == sh.ID {
929				cp := *h
930				rep.Outgoing = &cp
931			}
932			if h.ToShiftID == sh.ID {
933				rep.Incoming = append(rep.Incoming, *h)
934			}
935			for j := range h.Entries {
936				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
937					HandoverID: h.ID,
938					FromShift:  h.FromShiftID,
939					ToShift:    h.ToShiftID,
940					Entry:      h.Entries[j],
941				})
942			}
943		}
944		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
945		for k := range rep.Results {
946			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
947		}
948		return rep, nil
949	}
